// === Tab: mySketch ===
var noiseScale = 0.01,
	p = [],
	ang,
	radius, steps, start, delta;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	colorMode(HSB);
	for (var i = 0; i < 50; i++) {
		p[i] = {
			x: width / 2,
			y: height / 2
		};
	}
	ang = random(2 * PI);
	radius = max(width, height) / 8;
	delta = {
		x: 2 * radius * 0.86603,
		y: 1.5 * radius
	}
	steps = {
		x: floor(width / delta.x),
		y: floor(height / delta.y)
	}
	if (steps.y < steps.x) {
		steps.y = 7;
		steps.x = max(steps.x, steps.y);
		steps.x = steps.x + 7 - steps.x % 6;
	} else {
		steps.x = 7;
		steps.y = max(steps.y, steps.x);
		steps.y = steps.y + 3 - steps.y % 4;
	}
	start = {
		x: width / 2 - steps.x / 2 * delta.x - delta.x / 2,
		y: height / 2 - steps.y / 2 * delta.y - delta.y / 2
	}
	strokeWeight(3);
}

function draw() {
	var n, hue, part, mid;
	mid = {
		x: width / 2,
		y: height / 2
	}
	background(0);
	n = makeNoiseAndPath();
	hue = n * 720 % 360;
	part = 100 / p.length;
	translate(start.x, start.y);
	for (var k = 0; k < steps.y; k++) {
		translate(delta.x / 2 * (1 - (k % 2)), delta.y);
		for (var j = 0; j < steps.x; j++) {
			translate(delta.x, 0);
			escherRotate(k, j, 1);
			for (var m = p.length-2; m >-1; m--) {
				stroke((n * 720) % 360, 40, 100 - m / p.length * 100);
				//stroke((n * k*720) % 360, 40, 100 - m / p.length * 100);
				line(p[m].x - mid.x, p[m].y - mid.y, p[m + 1].x - mid.x, p[m + 1].y - mid.y);
			}
			noStroke();
			fill((n * 720) % 360, 40, 100);
			//fill((n * k*720) % 360, 40, 100);
			ellipse(p[0].x - mid.x, p[0].y - mid.y, 10, 10);
			escherRotate(k, j, -1);
		}
		translate(-delta.x * steps.x - delta.x / 2 * (1 - (k % 2)), 0);
	}
}

function makeNoiseAndPath() {
	var n, r;
	for (var i = p.length - 1; i > 0; i--) {
		p[i].x = p[i - 1].x;
		p[i].y = p[i - 1].y;
	}
	n = noise(p[0].x * noiseScale, p[0].y * noiseScale, ang * noiseScale);
	r = n * 12;
	ang += n * 2 - 1;
	p[0].x += r * cos(ang);
	p[0].y += r * sin(ang);
	if (p[0].x > width || p[0].x < 0 || p[0].y > height || p[0].y < 0) {
		p[0] = {
			x: 0.4 * width + random(0.2 * width),
			y: 0.4 * height + random(0.2 * height)
		}
		for (var i = 1; i < p.length; i++) {
			p[i] = {
				x: p[0].x,
				y: p[0].y
			}
		}
	}
	return n;
}

function escherRotate(k, j, direction) {
	if (k % 2 == 0) {
		rotate(direction * 2 * PI / 3);
	}
	if (j % 3 == 2) {
		rotate(direction * 2 * PI / 3);
	} else if (j % 3 == 1) {
		rotate(direction * 4 * PI / 3);
	}
}

function keyPressed() {
	if (keyCode == UP_ARROW || keyCode == DOWN_ARROW) {
		radius = (keyCode == UP_ARROW) ? radius * 1.1 : radius * 0.9;
		delta.x = 2 * radius * 0.86603;
		delta.y = 1.5 * radius;
		background(0);
		start.x = width / 2 - steps.x / 2 * delta.x - delta.x / 2;
		start.y = height / 2 - steps.y / 2 * delta.y - delta.y / 2;
	}
}

